export declare const cyberpunkNeonTheme = "/* \u8D5B\u535A\u670B\u514B\u98CE\u683C */\n#wemd {\n    padding: 5px 20px;\n    max-width: 677px;\n    margin: 0 auto;\n    font-family: -apple-system, BlinkMacSystemFont, \"Microsoft YaHei\", sans-serif;\n    color: #333;\n    /* \u6DF1\u8272\u6587\u5B57\uFF0C\u517C\u5BB9\u5FAE\u4FE1 */\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u4EAE\u8272/\u6DF1\u8272\u6A21\u5F0F */\n    word-break: break-word;\n}\n\n/* \u6B63\u6587 */\n#wemd p {\n    margin: 22px 0;\n    line-height: 1.75;\n    text-align: justify;\n    color: #444;\n    font-size: 16px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 - \u6545\u969C\u6846\u7EBF */\n#wemd h1 {\n    margin: 50px 0 40px;\n    text-align: center;\n}\n\n#wemd h1 .content {\n    font-size: 26px;\n    font-weight: 900;\n    color: #12161F;\n    /* \u6DF1\u8272\u6587\u5B57 */\n    display: inline-block;\n    border: 2px solid #00F3FF;\n    /* \u9752\u8272\u5B9E\u7EBF\u6846 */\n    padding: 12px 24px;\n    background: rgba(0, 243, 255, 0.1);\n    /* \u786C\u9634\u5F71\u6A21\u62DF\u6545\u969C\u9519\u4F4D */\n    box-shadow: 4px 4px 0px #FF00C1;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 - \u80FD\u91CF\u6761 */\n#wemd h2 {\n    margin: 45px 0 25px;\n    text-align: left;\n}\n\n#wemd h2 .content {\n    display: inline-block;\n    font-size: 20px;\n    font-weight: bold;\n    color: #12161F;\n    /* \u6DF1\u8272\u5B57 */\n    background-color: #00F3FF;\n    /* \u7EAF\u9752\u8272\u80CC\u666F */\n    padding: 6px 16px;\n    /* \u8D5B\u535A\u5207\u89D2 */\n    clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);\n    border-radius: 4px;\n    /* \u517C\u5BB9\u56DE\u9000 */\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 - \u7B80\u5355\u9AD8\u4EAE */\n#wemd h3 {\n    margin: 30px 0 15px;\n}\n\n#wemd h3 .content {\n    font-size: 18px;\n    font-weight: bold;\n    color: #FF00C1;\n    /* \u7C89\u8272\u6807\u9898 */\n    padding-left: 10px;\n    border-left: 4px solid #FF00C1;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 - \u7EC8\u7AEF\u63D0\u793A\u7B26 */\n#wemd h4 {\n    margin: 24px 0 10px;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: bold;\n    color: #00F3FF;\n}\n\n/* \u6A21\u62DF > \u7B26\u53F7 */\n#wemd h4 .content:before {\n    content: \"> \";\n    color: #FF00C1;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \u5F15\u7528 - \u7EC8\u7AEF\u6570\u636E\u5757 */\n#wemd .multiquote-1 {\n    margin: 30px 0;\n    padding: 20px;\n    background-color: rgba(0, 243, 255, 0.05);\n    border: 1px solid rgba(0, 243, 255, 0.3);\n    border-left: 4px solid #00F3FF;\n}\n\n#wemd .multiquote-1 p {\n    color: #444;\n    font-size: 14px;\n    margin: 0;\n    font-family: monospace;\n}\n\n#wemd .multiquote-2 {\n    margin: 28px 0;\n    padding: 18px;\n    background: rgba(255, 184, 77, 0.05);\n    border: 1px solid rgba(255, 184, 77, 0.3);\n    border-left: 4px solid #FFB84D;\n}\n\n#wemd .multiquote-2 p {\n    color: #444;\n    font-size: 14px;\n    margin: 0;\n    font-family: monospace;\n}\n\n#wemd .multiquote-3 {\n    margin: 26px 0;\n    padding: 16px;\n    background: rgba(255, 0, 193, 0.05);\n    border: 1px solid rgba(255, 0, 193, 0.3);\n    border-left: 4px solid #FF00C1;\n}\n\n#wemd .multiquote-3 p {\n    color: #444;\n    font-size: 14px;\n    margin: 0;\n    font-family: monospace;\n}\n\n/* \u5217\u8868 */\n#wemd ul {\n    list-style: disc;\n    padding-left: 20px;\n    color: #00F3FF;\n    margin: 20px 0;\n}\n\n#wemd ol {\n    list-style: decimal;\n    padding-left: 20px;\n    color: #FF00C1;\n    font-weight: bold;\n    margin: 20px 0;\n}\n\n#wemd ul ul {\n    list-style-type: square;\n    color: #FFB84D;\n    margin-top: 8px;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n    color: #00F3FF;\n}\n\n#wemd li section {\n    color: #444;\n    font-weight: normal;\n}\n\n/* \u94FE\u63A5 - \u80FD\u91CF\u94FE\u63A5 */\n#wemd a {\n    color: #00F3FF;\n    text-decoration: none;\n    border-bottom: 1px dashed #00F3FF;\n    transition: all 0.2s;\n}\n\n/* \u52A0\u7C97 - \u6545\u969C\u7C89\u9AD8\u4EAE */\n#wemd strong {\n    color: #FF00C1;\n    font-weight: bold;\n    text-shadow: 0 0 2px rgba(255, 0, 193, 0.4);\n}\n\n/* \u659C\u4F53 - \u7C89\u8272\u53D1\u5149 */\n#wemd em {\n    font-style: italic;\n    color: #FF00C1;\n    text-shadow: 0 0 3px rgba(255, 0, 193, 0.5);\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n    color: #00F3FF;\n    font-weight: bold;\n    text-shadow: 0 0 5px rgba(0, 243, 255, 0.5);\n}\n\n/* \u9AD8\u4EAE - \u9713\u8679\u80CC\u666F */\n#wemd mark {\n    background: rgba(255, 0, 193, 0.2);\n    color: #FF00C1;\n    padding: 2px 4px;\n    border: 1px solid rgba(255, 0, 193, 0.3);\n    box-shadow: 0 0 5px rgba(255, 0, 193, 0.2);\n}\n\n/* \u5220\u9664\u7EBF - \u53D1\u5149\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    text-decoration-color: #FF00C1;\n    color: #666;\n}\n\n/* \u5206\u5272\u7EBF - \u9713\u8679\u7EBF */\n#wemd hr {\n    margin: 50px 0;\n    border: none;\n    height: 2px;\n    background: linear-gradient(90deg, transparent, #00F3FF, transparent);\n    box-shadow: 0 0 10px rgba(0, 243, 255, 0.5);\n}\n\n/* \n * \u884C\u5185\u4EE3\u7801 - \u9ED1\u5BA2\u7EC8\u7AEF\u6307\u4EE4 (\u4FEE\u590D\u91CD\u70B9) \n * \u7EAF\u9ED1\u5E95 + \u9752\u8272\u5B57 + \u7B49\u5BBD\u5B57\u4F53 + \u5FAE\u53D1\u5149\n */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #00F3FF;\n    /* \u9713\u8679\u9752 */\n    background: #000000;\n    /* \u7EAF\u9ED1\u80CC\u666F */\n    border: 1px solid rgba(0, 243, 255, 0.3);\n    /* \u5FAE\u5F31\u7684\u9752\u8272\u8FB9\u6846 */\n    padding: 2px 6px;\n    margin: 0 4px;\n    border-radius: 4px;\n    font-size: 14px;\n    font-family: \"Courier New\", Courier, monospace;\n    /* \u5F3A\u5236\u7B49\u5BBD */\n    letter-spacing: 0px;\n}\n\n/* \u4EE3\u7801\u5757 - \u8D5B\u535A\u670B\u514B\u7EC8\u7AEF\u98CE\u683C */\n/* \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    background: #161B22;\n    /* \u7A0D\u5FAE\u4EAE\u4E00\u70B9\u7684\u6DF1\u8272\u80CC\u666F\uFF0C\u63D0\u9AD8\u53EF\u8BFB\u6027 */\n    border: 1px solid #00F3FF;\n    /* \u9713\u8679\u9752\u8272\u8FB9\u6846 */\n    border-left: 3px solid #00F3FF;\n    /* \u5DE6\u4FA7\u9713\u8679\u6761 */\n    font-family: \"Courier New\", \"Consolas\", \"Monaco\", monospace;\n    padding: 16px;\n    border-radius: 4px;\n    font-size: 13px;\n    overflow-x: auto;\n    white-space: pre;\n  min-width: max-content;\n    /* \u5FAE\u5999\u7684\u53D1\u5149\u6548\u679C */\n    box-shadow: \n        0 0 10px rgba(0, 243, 255, 0.2),\n        inset 0 0 20px rgba(0, 243, 255, 0.05);\n    /* \u5916\u53D1\u5149 + \u5185\u53D1\u5149 */\n    position: relative;\n}\n\n\n/* \u589E\u5F3A\u8BED\u6CD5\u9AD8\u4EAE\u989C\u8272\u7684\u5BF9\u6BD4\u5EA6\uFF0C\u786E\u4FDD\u5728\u6DF1\u8272\u80CC\u666F\u4E0B\u6E05\u6670\u53EF\u89C1 */\n/* \u57FA\u7840\u6587\u5B57\u989C\u8272 - \u786E\u4FDD\u9ED8\u8BA4\u6587\u5B57\u8DB3\u591F\u4EAE */\n#wemd pre code.hljs {\n    color: #E6EDF3;\n    /* \u975E\u5E38\u4EAE\u7684\u7070\u767D\u8272\u4F5C\u4E3A\u9ED8\u8BA4\u6587\u5B57\u989C\u8272 */\n}\n\n#wemd pre code.hljs .hljs-comment,\n#wemd pre code.hljs .hljs-quote {\n    color: #8B949E;\n    /* \u6CE8\u91CA\u7528\u4E2D\u7B49\u4EAE\u5EA6\u7684\u7070\u8272 */\n    opacity: 0.9;\n}\n\n#wemd pre code.hljs .hljs-keyword,\n#wemd pre code.hljs .hljs-selector-tag,\n#wemd pre code.hljs .hljs-subst {\n    color: #FF7B72;\n    /* \u4EAE\u7EA2\u6A59\u8272\u5173\u952E\u5B57 */\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-string,\n#wemd pre code.hljs .hljs-doctag {\n    color: #FFA657;\n    /* \u4EAE\u6A59\u8272\u5B57\u7B26\u4E32 */\n}\n\n#wemd pre code.hljs .hljs-number,\n#wemd pre code.hljs .hljs-literal,\n#wemd pre code.hljs .hljs-variable,\n#wemd pre code.hljs .hljs-template-variable {\n    color: #79C0FF;\n    /* \u4EAE\u84DD\u8272\u6570\u5B57\u548C\u53D8\u91CF */\n}\n\n#wemd pre code.hljs .hljs-title,\n#wemd pre code.hljs .hljs-section,\n#wemd pre code.hljs .hljs-selector-id {\n    color: #D2A8FF;\n    /* \u4EAE\u7D2B\u8272\u51FD\u6570\u540D */\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-type,\n#wemd pre code.hljs .hljs-class .hljs-title {\n    color: #FFA657;\n    /* \u6A59\u8272\u7C7B\u578B\uFF0C\u63D0\u9AD8\u5BF9\u6BD4\u5EA6 */\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-tag,\n#wemd pre code.hljs .hljs-name,\n#wemd pre code.hljs .hljs-attribute {\n    color: #79C0FF;\n    /* \u4EAE\u84DD\u8272\u6807\u7B7E */\n}\n\n#wemd pre code.hljs .hljs-regexp,\n#wemd pre code.hljs .hljs-link {\n    color: #56D4DD;\n    /* \u4EAE\u9752\u8272\u6B63\u5219\u8868\u8FBE\u5F0F */\n}\n\n#wemd pre code.hljs .hljs-symbol,\n#wemd pre code.hljs .hljs-bullet {\n    color: #FF7B72;\n    /* \u4EAE\u7EA2\u6A59\u8272\u7B26\u53F7 */\n}\n\n#wemd pre code.hljs .hljs-built_in,\n#wemd pre code.hljs .hljs-builtin-name {\n    color: #58A6FF;\n    /* \u4EAE\u84DD\u8272\u5185\u7F6E\u51FD\u6570 */\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-meta {\n    color: #8B949E;\n    /* \u5143\u6570\u636E\u7528\u7070\u8272 */\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-deletion {\n    background: rgba(255, 123, 114, 0.2);\n    /* \u5220\u9664\u7EBF\u80CC\u666F */\n    color: #FF7B72;\n}\n\n#wemd pre code.hljs .hljs-addition {\n    background: rgba(121, 192, 255, 0.2);\n    /* \u6DFB\u52A0\u7EBF\u80CC\u666F */\n    color: #79C0FF;\n}\n\n#wemd pre code.hljs .hljs-emphasis {\n    font-style: italic;\n    color: #E6EDF3;\n}\n\n#wemd pre code.hljs .hljs-strong {\n    font-weight: bold;\n    color: #FF7B72;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u9713\u8679\u9752\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #00F3FF;\n    background: #161B22;\n    border: 1px solid #00F3FF;\n    border-left: 3px solid #00F3FF;\n    box-shadow: \n        0 0 10px rgba(0, 243, 255, 0.2),\n        inset 0 0 20px rgba(0, 243, 255, 0.05);\n}\n\n/* \u8868\u683C - \u6570\u636E\u9762\u677F */\n#wemd table {\n    width: 100%;\n    border-collapse: separate;\n    border-spacing: 0;\n    margin: 30px 0;\n    font-size: 14px;\n    border: 1px solid rgba(0, 243, 255, 0.3);\n    background: transparent;\n}\n\n#wemd table tr th {\n    background: rgba(0, 243, 255, 0.1);\n    color: #00F3FF;\n    border-bottom: 1px solid rgba(0, 243, 255, 0.3);\n    padding: 10px;\n    font-weight: bold;\n    text-align: left;\n}\n\n#wemd table tr td {\n    border-bottom: 1px solid rgba(0, 243, 255, 0.2);\n    padding: 10px;\n    color: #444;\n    background: transparent;\n}\n\n#wemd figcaption {\n    margin-top: 10px;\n    text-align: center;\n    color: #00F3FF;\n    font-size: 13px;\n    font-family: monospace;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #FF00C1;\n}\n\n#wemd .footnotes-sep {\n    border-top: 1px solid #30363D;\n    padding-top: 20px;\n    margin-top: 40px;\n    font-size: 12px;\n    color: #555;\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #0d1117;\n    background: #00F3FF;\n    margin-right: 4px;\n    font-size: 11px;\n    padding: 1px 4px;\n}\n\n#wemd .footnote-item p {\n    color: #666;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* \u516C\u5F0F - \u4FDD\u6301\u9ED8\u8BA4\u989C\u8272\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u4EAE\u8272/\u6DF1\u8272\u6A21\u5F0F */\n#wemd .block-equation > svg,\n#wemd .katex-block > svg,\n#wemd mjx-container[display=\"true\"] svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg,\n#wemd .katex-inline > svg,\n#wemd mjx-container:not([display=\"true\"]) svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u8D5B\u535A\u670B\u514B\u98CE\u683C */\n#wemd .callout {\n    margin: 30px 0;\n    padding: 20px;\n    background: rgba(0, 243, 255, 0.05);\n    border: 1px solid rgba(0, 243, 255, 0.2);\n    border-radius: 4px;\n    color: #444;\n}\n\n#wemd .callout-title {\n    font-weight: bold;\n    margin-bottom: 10px;\n    color: #00F3FF;\n    text-shadow: 0 0 5px rgba(0, 243, 255, 0.5);\n    font-size: 16px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { \n    border-left: 3px solid #00F3FF;\n    box-shadow: 0 0 10px rgba(0, 243, 255, 0.2);\n}\n\n#wemd .callout-tip { \n    border-left: 3px solid #FF00C1;\n    box-shadow: 0 0 10px rgba(255, 0, 193, 0.2);\n}\n\n#wemd .callout-important { \n    border-left: 3px solid #00F3FF;\n    box-shadow: 0 0 10px rgba(0, 243, 255, 0.2);\n}\n\n#wemd .callout-warning { \n    border-left: 3px solid #FFB84D;\n    box-shadow: 0 0 10px rgba(255, 184, 77, 0.2);\n}\n\n#wemd .callout-caution { \n    border-left: 3px solid #FF00C1;\n    box-shadow: 0 0 10px rgba(255, 0, 193, 0.2);\n}\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
